// SkadiAsset.swift — baked Skadi (the Corrupting Heart) animation clips.
//
// Two forms, both chibi-scale, rendered OFFLINE from arkdock's Spine data via
// headless pixi-spine, quantized, base64-embedded (bare-binary friendly):
//   · base (default_build, 200px frames): Relax / Move / Interact / Sleep
//   · deployed battle (default_front, 300px frames): Idle / Skill_2 / Skill_3
// renderOperator drives a behaviour state machine over these — combat behaviours
// while an agent works, base behaviours while idle. See tools/bake-operator/.

import CoreGraphics
import Foundation
import ImageIO

enum SkadiAsset {
    nonisolated(unsafe) static let relax      = slice(decode(relaxB64), 200)
    nonisolated(unsafe) static let move       = slice(decode(moveB64), 200)
    nonisolated(unsafe) static let interact   = slice(decode(interactB64), 200)
    nonisolated(unsafe) static let sleep      = slice(decode(sleepB64), 200)
    nonisolated(unsafe) static let battleIdle = slice(decode(battleIdleB64), 300)
    nonisolated(unsafe) static let skill2     = slice(decode(skill2B64), 300)
    nonisolated(unsafe) static let skill3     = slice(decode(skill3B64), 300)

    private static func decode(_ b64: String) -> CGImage? {
        guard let data = Data(base64Encoded: b64),
              let src = CGImageSourceCreateWithData(data as CFData, nil),
              let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
        return img
    }

    private static func slice(_ sheet: CGImage?, _ frameW: Int) -> [CGImage] {
        guard let sheet = sheet, sheet.width >= frameW else { return [] }
        var out: [CGImage] = []
        for i in 0..<(sheet.width / frameW) {
            if let f = sheet.cropping(to: CGRect(x: i * frameW, y: 0,
                                                 width: frameW, height: sheet.height)) {
                out.append(f)
            }
        }
        return out
    }

